// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    function setUp() public { c = new DepositLog(); }
    function testFuzz_property(address k1, address k2) public {
        vm.assume(k1 != k2);
        vm.assume(k1 != address(0) && k2 != address(0));
        // _contractOwner is never assigned, so the owner is address(0)
        vm.prank(address(0));
        c.setApprovedLogger(k1, true);
        vm.prank(address(0));
        c.setApprovedLogger(k2, false);
        assertTrue(c.approvedLoggers(k1));
    }
}
